sys_script.script:
(function executeRule(current, previous /*null when async*/) {
    var emails = [];
    var seen = {};

    // 1. Dynamically look up members of any active Receptionist(s) group by name
    var grp = new GlideRecord('sys_user_group');
    grp.addQuery('name', 'CONTAINS', 'Receptionist');
    grp.addActiveQuery();
    grp.query();
    while (grp.next()) {
        var mem = new GlideRecord('sys_user_grmember');
        mem.addQuery('group', grp.getUniqueValue());
        mem.query();
        while (mem.next()) {
            var u = mem.user.getRefRecord();
            if (u.isValidRecord() && u.active == true && u.email) {
                var em = u.getValue('email');
                if (!seen[em]) {
                    seen[em] = true;
                    emails.push(em);
                }
            }
        }
    }

    // 2. Fallback: active users holding the receptionist role directly (works on fresh instances without groups)
    if (emails.length === 0) {
        var hr = new GlideRecord('sys_user_has_role');
        hr.addQuery('role.name', 'x_2206701_hotel_0.receptionist');
        hr.addQuery('user.active', true);
        hr.query();
        while (hr.next()) {
            var ru = hr.user.getRefRecord();
            if (ru.isValidRecord() && ru.email && ru.getValue('user_name') != 'admin') {
                var rem = ru.getValue('email');
                if (!seen[rem]) {
                    seen[rem] = true;
                    emails.push(rem);
                }
            }
        }
    }

    if (emails.length > 0) {
        var actionLabel = current.operation() == 'insert' ? 'Created' : 'Updated';
        gs.eventQueue('x_2206701_hotel_0.reservation.changed', current, emails.join(','), actionLabel);
    }
})(current, previous);
